"use client"

// Bollard UI — mrz-paste-input · MIT licence · https://bollard-ui.vercel.app/components/mrz-paste-input

import * as React from "react"
import { CircleAlert, CircleCheck, CircleX, ScanLine, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { parseMrz, type MrzField, type MrzIssue, type MrzResult } from "./mrz"

export { checkDigit, cleanMrz, parseMrz, type MrzField, type MrzFields, type MrzIssue, type MrzResult } from "./mrz"

/** Every visible string. `{…}` placeholders are filled in. */
export const MRZ_MESSAGES = {
  label: "Passport MRZ",
  hint: "Paste or type the two lines of letters and < at the bottom of the photo page.",
  line: "Line {n}: {count}/44",
  name: "Name",
  number: "Passport no.",
  nationality: "Nationality",
  birthDate: "Date of birth",
  expiryDate: "Expires",
  sex: "Sex",
  sexes: { M: "Male", F: "Female", X: "Unspecified", "<": "Unspecified" } as Record<string, string>,
  checked: "check digit OK",
  failed: "check digit wrong",
  pending: "check digit OK only after the fix below",
  length: "A passport MRZ is 2 lines of 44 characters. This has {lengths}.",
  padLine: "Fill line 1 with <",
  idCard: "This looks like an ID card ({format}), not a passport. Paste the passport's two 44-character lines.",
  swapped: "The lines are in the wrong order: the line starting with P comes first.",
  swap: "Swap lines",
  notPassport: "Line 1 starts with {code}. A passport MRZ starts with P.",
  badChar: "Line {line} has \"{char}\" at position {position}. An MRZ only has A–Z, 0–9 and <.",
  ocrDigits: "\"{from}\" in a date or check digit should be \"{to}\": those places are numbers only.",
  ocrLetters: "\"{from}\" in the name or country should be \"{to}\": those places are letters only.",
  ocrFiller: "\"{from}\" here is probably the < filler read as K.",
  ocrSeparator: "No << between surname and given names. Was \"KK\" meant to be <<?",
  useFix: "Use {to}",
  check: "The {field} check digit is {found} but the {field} works out to {expected}.",
  checkComposite: "The final check digit is {found} but the line works out to {expected}.",
  fixDigit: "Make it {to}",
  fixData: "Read {from} as {to}",
  fields: { number: "passport number", birthDate: "date of birth", expiryDate: "expiry date", personalNumber: "personal number", composite: "final" } as Record<MrzField, string>,
  badDate: "{value} isn't a real date ({field}).",
  unknownBirthDate: "Part of the date of birth is unknown (shown as <), which passports are allowed to do. Check what your form expects.",
  birthYear: "{year}, day or month unknown",
  truncated: "The name fills the whole line, so it may be cut short. Check it against the photo page.",
  expired: "This passport expired on {date}.",
  expiresSoon: "This passport expires on {date}, in {days} days. Many countries want 6 months left.",
  valid: "MRZ checks out",
}
export type MrzMessages = typeof MRZ_MESSAGES

const fill = (s: string, v: Record<string, string | number | undefined>) => s.replace(/\{(\w+)\}/g, (m, k: string) => String(v[k] ?? m))

export interface MrzPasteInputProps extends Omit<React.ComponentProps<"textarea">, "value" | "defaultValue" | "onChange"> {
  /** Controlled MRZ text. */
  value?: string
  /** Initial text when uncontrolled. */
  defaultValue?: string
  /** Called with the text on every edit or fix. */
  onValueChange?: (value: string) => void
  /** Called when the parse result changes; `result.valid` is true once every check passes. */
  onParse?: (result: MrzResult) => void
  /** "Today", for the expiry check and the birth-year century. Pass it for deterministic rendering. */
  today?: Date
  /** Locale for dates. */
  locale?: string
  /** Pause in ms before problems are read out after typing. */
  delay?: number
  /** Any visible string; `fields` and `sexes` may be partial. */
  messages?: Partial<Omit<MrzMessages, "fields" | "sexes">> & { fields?: Partial<MrzMessages["fields"]>; sexes?: Partial<MrzMessages["sexes"]> }
}

/**
 * Turns a pasted or typed passport MRZ (ICAO 9303 TD3) into checked fields so a booking or KYC form never
 * stores a misread passport number or date. It verifies every check digit, catches OCR slips (O for 0, K for <,
 * swapped lines, CRLF and stray spaces), proposes the likeliest fix for a wrong check digit and flags an
 * expired or soon-expiring passport.
 */
export function MrzPasteInput({
  value, defaultValue = "", onValueChange, onParse, today, locale = "en-IN", delay = 700, messages,
  className, id: idProp, "aria-describedby": describedBy, ...props
}: MrzPasteInputProps) {
  const t = { ...MRZ_MESSAGES, ...messages, fields: { ...MRZ_MESSAGES.fields, ...messages?.fields }, sexes: { ...MRZ_MESSAGES.sexes, ...messages?.sexes } }
  const [inner, setInner] = React.useState(defaultValue)
  const text = value ?? inner
  const now = React.useMemo(() => today ?? new Date(), [today])
  const result = React.useMemo(() => parseMrz(text, now), [text, now])
  const rootRef = React.useRef<HTMLDivElement>(null)
  const areaRef = React.useRef<HTMLTextAreaElement>(null)
  const [status, setStatus] = React.useState("")
  const autoId = React.useId()
  const id = idProp ?? `${autoId}-mrz`

  const date = (iso: string | null) => (iso ? new Intl.DateTimeFormat(locale, { timeZone: "UTC", day: "numeric", month: "short", year: "numeric" }).format(Date.parse(iso)) : "—")
  const commit = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }
  /** After a fix, go to the next fix, else back to the field. */
  const applyFix = (fixed: string) => {
    commit(fixed)
    requestAnimationFrame(() => (rootRef.current?.querySelector<HTMLElement>("[data-fix]") ?? areaRef.current)?.focus())
  }
  const fix = (label: string, fixed: string) => (
    <button key={label} type="button" data-fix onClick={() => applyFix(fixed)}
      className="inline-flex h-6 items-center rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors outline-none hover:bg-amber-500/10 focus-visible:ring-[3px] focus-visible:ring-ring/50 dark:text-amber-200">
      {label}
    </button>
  )

  const render = (issue: MrzIssue): [string, React.ReactNode[]] => {
    switch (issue.kind) {
      case "length": return [fill(t.length, { lengths: issue.lengths.join(" + ") }), issue.fixed ? [fix(t.padLine, issue.fixed)] : []]
      case "idCard": return [fill(t.idCard, { format: issue.format }), []]
      case "swapped": return [t.swapped, [fix(t.swap, issue.fixed)]]
      case "notPassport": return [fill(t.notPassport, { code: issue.code }), []]
      case "badChar": return [fill(t.badChar, { line: issue.line, position: issue.position, char: issue.char }), []]
      case "ocr": {
        const msg = issue.what === "digits" ? t.ocrDigits : issue.what === "letters" ? t.ocrLetters : issue.certain ? t.ocrFiller : t.ocrSeparator
        return [fill(msg, { from: issue.from, to: issue.to }), [fix(fill(t.useFix, { to: issue.to }), issue.fixed)]]
      }
      case "check": {
        const msg = fill(issue.field === "composite" ? t.checkComposite : t.check, { field: t.fields[issue.field], found: issue.found, expected: issue.expected })
        return [msg, issue.fixes.map((f) => fix(fill(f.change === "digit" ? t.fixDigit : t.fixData, f), f.fixed))]
      }
      case "badDate": return [fill(t.badDate, { value: issue.value, field: t.fields[issue.field] }), []]
      case "unknownBirthDate": return [t.unknownBirthDate, []]
      case "truncated": return [t.truncated, []]
      case "expired": return [fill(t.expired, { date: date(issue.date) }), []]
      case "expiresSoon": return [fill(t.expiresSoon, { date: date(issue.date), days: issue.days }), []]
    }
  }

  const parseKey = JSON.stringify(result)
  const onParseRef = React.useRef(onParse)
  onParseRef.current = onParse
  React.useEffect(() => {
    if (text) onParseRef.current?.(JSON.parse(parseKey) as MrzResult)
  }, [parseKey]) // eslint-disable-line react-hooks/exhaustive-deps

  const spoken = text ? (result.issues.length ? result.issues.map((i) => render(i)[0]).join(" ") : t.valid) : ""
  React.useEffect(() => {
    const timer = setTimeout(() => setStatus(spoken), delay)
    return () => clearTimeout(timer)
  }, [spoken, delay])

  const badDates = new Set<string>(result.issues.flatMap((i) => (i.kind === "badDate" ? [i.field] : [])))
  const state = (check: MrzField) => (badDates.has(check) ? "fail" : result.checks[check] ?? "fail")
  const unknownDob = result.issues.find((i) => i.kind === "unknownBirthDate")
  const f = result.fields
  const row = (label: string, content: React.ReactNode, check?: MrzField, bad?: boolean) => (
    <div className="grid min-w-0 gap-0.5">
      <dt className="text-xs text-muted-foreground">{label}</dt>
      <dd className={cn("flex min-w-0 items-center gap-1 font-medium break-words", bad && "text-red-700 dark:text-red-400")}>
        <span className="min-w-0">{content}</span>
        {check && (state(check) === "fail"
          ? <CircleX role="img" aria-label={t.failed} className="size-3.5 shrink-0 text-red-600 dark:text-red-400" />
          : state(check) === "pending"
            ? <CircleAlert role="img" aria-label={t.pending} className="size-3.5 shrink-0 text-amber-600 dark:text-amber-400" />
            : <CircleCheck role="img" aria-label={t.checked} className="size-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />)}
      </dd>
    </div>
  )
  const lines = result.lines.length ? result.lines : [""]
  const expired = result.issues.some((i) => i.kind === "expired")

  return (
    <div ref={rootRef} data-slot="mrz-paste-input" data-state={!text ? "empty" : result.valid ? (expired ? "expired" : "valid") : "invalid"} className={cn("grid w-full max-w-md min-w-0 gap-2 text-sm", className)}>
      <label htmlFor={id} className="flex items-center gap-1.5 font-medium">
        <ScanLine aria-hidden className="size-4 text-muted-foreground" />
        {t.label}
      </label>
      <textarea
        ref={areaRef}
        id={id}
        rows={2}
        wrap="off"
        spellCheck={false}
        autoCapitalize="characters"
        autoComplete="off"
        value={text}
        aria-invalid={(!!text && !result.valid) || undefined}
        aria-describedby={cn(`${autoId}-hint`, text && `${autoId}-res`, describedBy) || undefined}
        onChange={(e) => commit(e.target.value)}
        className="min-h-16 w-full min-w-0 resize-none overflow-x-auto rounded-md border bg-transparent px-3 py-2 font-mono text-xs leading-5 tracking-wide uppercase shadow-xs outline-none placeholder:normal-case focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive dark:bg-input/30"
        {...props}
      />
      <p id={`${autoId}-hint`} className="flex flex-wrap justify-between gap-x-3 text-xs text-muted-foreground">
        <span>{t.hint}</span>
        {text && (
          <span className="tabular-nums">
            {lines.slice(0, 3).map((l, i) => (
              <span key={i} className={cn("mr-2", l.length !== 44 && "text-amber-700 dark:text-amber-400")}>{fill(t.line, { n: i + 1, count: l.length })}</span>
            ))}
          </span>
        )}
      </p>

      {text && (
        <div id={`${autoId}-res`} className="grid gap-2">
          {f && (
            <dl className="grid grid-cols-2 gap-x-3 gap-y-2 rounded-md bg-muted/50 px-3 py-2">
              <div className="col-span-2">{row(t.name, `${f.surname}${f.givenNames ? `, ${f.givenNames}` : ""}` || "—")}</div>
              {row(t.number, <span className="font-mono">{f.number || "—"}</span>, "number")}
              {row(t.nationality, f.nationality || "—")}
              {row(t.birthDate, unknownDob?.kind === "unknownBirthDate" && unknownDob.year ? fill(t.birthYear, { year: unknownDob.year }) : date(f.birthDate), "birthDate")}
              {row(t.expiryDate, date(f.expiryDate), "expiryDate", expired)}
              {row(t.sex, t.sexes[f.sex] ?? f.sex)}
            </dl>
          )}
          {result.issues.length > 0 ? (
            <ul className="grid gap-2">
              {result.issues.map((issue, i) => {
                const [msg, fixes] = render(issue)
                const red = issue.kind === "expired"
                const Icon = red ? CircleX : TriangleAlert
                return (
                  <li key={`${issue.kind}-${i}`} className={cn("flex gap-1.5 text-xs", red ? "font-medium text-red-700 dark:text-red-400" : "text-amber-700 dark:text-amber-400")}>
                    <Icon aria-hidden className="mt-0.5 size-3.5 shrink-0" />
                    <span className="min-w-0 space-y-1">
                      <span className="block break-words">{msg}</span>
                      {fixes.length > 0 && <span className="flex flex-wrap gap-2">{fixes}</span>}
                    </span>
                  </li>
                )
              })}
            </ul>
          ) : (
            <p className="flex items-center gap-1.5 text-xs text-emerald-700 dark:text-emerald-400"><CircleCheck aria-hidden className="size-3.5" />{t.valid}</p>
          )}
        </div>
      )}
      <span aria-live="polite" className="sr-only">{status}</span>
    </div>
  )
}

// Bollard UI — mrz-paste-input · MIT licence · https://bollard-ui.vercel.app/components/mrz-paste-input

/**
 * ICAO Doc 9303 TD3 (passport) machine readable zone: two lines of 44 characters.
 * Part 3 §4.9: check digits use weights 7-3-1, modulus 10, with 0–9 = 0–9, A–Z = 10–35 and "<" = 0.
 * Part 4 §4.2.2: line 2 holds the document number (1–9, check 10), nationality (11–13), date of birth (14–19,
 * check 20), sex (21), date of expiry (22–27, check 28), personal number (29–42, check 43) and a composite
 * check (44) over positions 1–10, 14–20 and 22–43.
 */

export interface MrzFields {
  /** "P" plus the type letter, e.g. "P<" or "PD". */
  documentCode: string
  issuingState: string
  surname: string
  givenNames: string
  number: string
  nationality: string
  /** YYYY-MM-DD, century guessed from today. */
  birthDate: string | null
  sex: "M" | "F" | "X" | "<"
  expiryDate: string | null
  personalNumber: string
}

export type MrzField = "number" | "birthDate" | "expiryDate" | "personalNumber" | "composite"

export type MrzIssue =
  | { kind: "length"; lengths: number[]; fixed?: string }
  | { kind: "idCard"; format: "TD1" | "TD2" }
  | { kind: "swapped"; fixed: string }
  | { kind: "notPassport"; code: string }
  | { kind: "badChar"; line: 1 | 2; position: number; char: string }
  | { kind: "ocr"; what: "digits" | "letters" | "filler"; line: 1 | 2; positions: number[]; from: string; to: string; fixed: string; certain: boolean }
  | { kind: "check"; field: MrzField; found: string; expected: string; fixes: { fixed: string; change: "digit" | "data"; from: string; to: string }[] }
  | { kind: "badDate"; field: "birthDate" | "expiryDate"; value: string }
  /** 9303-3 §4.8: an unknown day, month or year of birth is written as "<". Not an error; `year` is set when known. */
  | { kind: "unknownBirthDate"; year: number | null }
  | { kind: "truncated" }
  | { kind: "expired"; date: string; days: number }
  | { kind: "expiresSoon"; date: string; days: number }

export interface MrzResult {
  /** The two cleaned lines, or what could be cleaned. */
  lines: string[]
  fields: MrzFields | null
  issues: MrzIssue[]
  /** True when the MRZ as pasted passes every structural and check-digit test. */
  valid: boolean
  /**
   * Each check digit as pasted: "ok", "fail", or "pending" when it only passes once a suggested OCR fix is taken.
   * Fields and dates are read as if the certain OCR fixes were taken, so use this before trusting a value.
   */
  checks: Partial<Record<MrzField, "ok" | "fail" | "pending">>
}

const MAX_INPUT = 600
const VALUE = (c: string) => (c >= "0" && c <= "9" ? c.charCodeAt(0) - 48 : c >= "A" && c <= "Z" ? c.charCodeAt(0) - 55 : c === "<" ? 0 : NaN)

/** ICAO 9303 check digit of `s`, or NaN if it holds a character the MRZ can't contain. */
export function checkDigit(s: string): number {
  let sum = 0
  for (let i = 0; i < s.length; i++) sum += VALUE(s[i]) * [7, 3, 1][i % 3]
  return sum % 10
}

/** Pasted text → MRZ lines: drops a BOM, CRLF, spaces and zero-width marks, upper-cases and maps «‹ to "<". */
export function cleanMrz(text: unknown): string[] {
  const s = String(text ?? "").slice(0, MAX_INPUT).replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").toUpperCase()
  const lines = s.split("\n").map((l) => l.replace(/[\s\u200B-\u200D\u2060]/g, "").replace(/[«‹〈＜]/g, "<")).filter(Boolean)
  if (lines.length === 1 && lines[0].length === 88) return [lines[0].slice(0, 44), lines[0].slice(44)]
  return lines
}

const DIGIT_FOR: Record<string, string> = { O: "0", Q: "0", D: "0", U: "0", I: "1", L: "1", Z: "2", S: "5", G: "6", B: "8", T: "7" }
const LETTER_FOR: Record<string, string> = { "0": "O", "1": "I", "2": "Z", "5": "S", "6": "G", "8": "B" }
const LOOKALIKE: Record<string, string[]> = { "0": ["O", "D", "Q"], O: ["0"], D: ["0"], Q: ["0"], "1": ["I", "L"], I: ["1"], L: ["1"], "2": ["Z"], Z: ["2"], "5": ["S"], S: ["5"], "6": ["G"], G: ["6"], "8": ["B"], B: ["8"] }

/** Line 2 positions (0-based) that must be digits: check digits and both dates. */
const DIGIT_POS = [9, 13, 14, 15, 16, 17, 18, 19, 21, 22, 23, 24, 25, 26, 27, 43]
const join = (a: string, b: string) => `${a}\n${b}`
const put = (s: string, i: number, c: string) => s.slice(0, i) + c + s.slice(i + 1)

function date(yymmdd: string, kind: "birth" | "expiry", today: Date): string | null {
  if (!/^\d{6}$/.test(yymmdd)) return null
  const yy = +yymmdd.slice(0, 2), mm = +yymmdd.slice(2, 4), dd = +yymmdd.slice(4, 6)
  const now = today.getUTCFullYear()
  let year = 2000 + yy
  const todayDay = Date.UTC(now, today.getUTCMonth(), today.getUTCDate())
  if (kind === "birth" && Date.UTC(year, mm - 1, dd) > todayDay) year -= 100
  if (kind === "expiry" && year > now + 30) year -= 100
  const d = new Date(Date.UTC(year, mm - 1, dd))
  return d.getUTCMonth() === mm - 1 && d.getUTCDate() === dd ? d.toISOString().slice(0, 10) : null
}

const FIELDS: { field: MrzField; start: number; end: number; check: number; letters: boolean }[] = [
  { field: "number", start: 0, end: 9, check: 9, letters: true },
  { field: "birthDate", start: 13, end: 19, check: 19, letters: false },
  { field: "expiryDate", start: 21, end: 27, check: 27, letters: false },
  { field: "personalNumber", start: 28, end: 42, check: 42, letters: true },
]
const compositeOf = (l2: string) => l2.slice(0, 10) + l2.slice(13, 20) + l2.slice(21, 43)
const fieldOk = (l2: string, f: (typeof FIELDS)[number]) => {
  const data = l2.slice(f.start, f.end)
  const cd = l2[f.check]
  // 9303-4: with no personal number, its check digit may be "<" or 0.
  if (f.field === "personalNumber" && /^<*$/.test(data) && (cd === "<" || cd === "0")) return true
  return String(checkDigit(data)) === cd
}
const compositeOk = (l2: string) => String(checkDigit(compositeOf(l2))) === l2[43]

/** Validates a pasted TD3 MRZ, explains every problem and offers corrected text for each fixable one. Never throws. */
export function parseMrz(text: unknown, today: Date = new Date()): MrzResult {
  const lines = cleanMrz(text)
  const issues: MrzIssue[] = []
  const now = Number.isNaN(today?.getTime?.()) ? new Date() : today
  if (!lines.length) return { lines, fields: null, issues, valid: false, checks: {} }

  if (lines.length === 3 && lines.every((l) => l.length === 30)) return { lines, fields: null, issues: [{ kind: "idCard", format: "TD1" }], valid: false, checks: {} }
  if (lines.length === 2 && lines.every((l) => l.length === 36)) return { lines, fields: null, issues: [{ kind: "idCard", format: "TD2" }], valid: false, checks: {} }
  if (lines.length !== 2 || lines.some((l) => l.length !== 44)) {
    // Copying often drops the trailing "<" fillers of the name line: pad it back when line 2 is complete.
    const [a, b] = lines
    const fixed = lines.length === 2 && a.startsWith("P") && a.length >= 30 && a.length < 44 && b.length === 44 ? join(a.padEnd(44, "<"), b) : undefined
    return { lines, fields: null, issues: [{ kind: "length", lengths: lines.map((l) => l.length), fixed }], valid: false, checks: {} }
  }

  let [l1, l2] = lines
  if (!l1.startsWith("P") && l2.startsWith("P")) {
    issues.push({ kind: "swapped", fixed: join(l2, l1) })
    ;[l1, l2] = [l2, l1]
  }
  if (!l1.startsWith("P")) issues.push({ kind: "notPassport", code: l1.slice(0, 2) })

  // OCR slips the reader could not have meant: letters in digit-only places, digits in names, "K" read for "<".
  // Each fix is offered on its own; validation below runs as if every certain fix were taken, and `checks`
  // marks the fields that only pass because of one. Uncertain fixes are offered but never assumed.
  const [b1, b2] = [l1, l2]
  const pending2 = new Set<number>()
  const ocr = (what: "digits" | "letters" | "filler", line: 1 | 2, positions: number[], map: (c: string) => string, certain = true) => {
    if (!positions.length) return
    const apply = (s: string) => positions.reduce((a, p) => put(a, p, map(a[p])), s)
    const cur = line === 1 ? l1 : l2
    const from = positions.map((p) => cur[p]).join("")
    const to = positions.map((p) => map(cur[p])).join("")
    if (certain && line === 1) l1 = apply(l1)
    else if (certain) { l2 = apply(l2); positions.forEach((p) => pending2.add(p)) }
    issues.push({ kind: "ocr", what, line, positions, from, to, fixed: line === 1 ? join(apply(b1), b2) : join(b1, apply(b2)), certain })
  }
  const positionsIn = (s: string, from: number, to: number, test: (c: string) => boolean) => Array.from({ length: to - from }, (_, i) => from + i).filter((p) => test(s[p]))
  ocr("digits", 2, DIGIT_POS.filter((p) => DIGIT_FOR[l2[p]]), (c) => DIGIT_FOR[c])
  ocr("letters", 1, positionsIn(l1, 2, 44, (c) => !!LETTER_FOR[c]), (c) => LETTER_FOR[c])
  ocr("letters", 2, positionsIn(l2, 10, 13, (c) => !!LETTER_FOR[c]), (c) => LETTER_FOR[c])
  // A run of "<" and "K" at the end of the name: every K after the first "<" was a misread filler.
  const tailStart = 44 - (/[<K]*$/.exec(l1.slice(5))?.[0].length ?? 0)
  const firstFill = l1.indexOf("<", tailStart)
  ocr("filler", 1, firstFill < 0 ? [] : positionsIn(l1, firstFill, 44, (c) => c === "K"), () => "<")
  const opt = l2.slice(28, 42)
  if (/^[<K]+$/.test(opt) && /K/.test(opt) && /</.test(opt)) ocr("filler", 2, positionsIn(l2, 28, 42, (c) => c === "K"), () => "<")
  // No "<<" between surname and given names but a "KK" between letters: probably the separator. Only a suggestion.
  const nameZone = l1.slice(5).replace(/<+$/, "")
  const kk = nameZone.includes("<<") ? null : /[A-Z]KK[A-Z]/.exec(nameZone)
  if (kk) ocr("filler", 1, [5 + kk.index + 1, 5 + kk.index + 2], () => "<", false)

  for (const [line, s] of [[1, l1], [2, l2]] as const)
    for (let i = 0; i < 44; i++) if (Number.isNaN(VALUE(s[i]))) issues.push({ kind: "badChar", line, position: i + 1, char: s[i] })
  if (issues.some((i) => i.kind === "badChar")) return { lines: [l1, l2], fields: null, issues, valid: false, checks: {} }

  // Check digits, each with the likeliest fix: a lookalike character in the data, or the check digit itself.
  const checks: MrzResult["checks"] = {}
  const touched = (from: number, to: number) => [...pending2].some((p) => p >= from && p <= to)
  for (const f of FIELDS) {
    checks[f.field] = fieldOk(l2, f) ? (touched(f.start, f.check) ? "pending" : "ok") : "fail"
    if (fieldOk(l2, f)) continue
    const data = l2.slice(f.start, f.end)
    const fixes: { fixed: string; change: "digit" | "data"; from: string; to: string }[] = []
    if (f.letters)
      for (let i = f.start; i < f.end; i++)
        for (const alt of LOOKALIKE[l2[i]] ?? []) {
          const next = put(l2, i, alt)
          if (fieldOk(next, f) && compositeOk(next)) fixes.push({ fixed: join(l1, next), change: "data", from: l2[i], to: alt })
        }
    const withDigit = put(l2, f.check, String(checkDigit(data)))
    if (compositeOk(withDigit) || !fixes.length) fixes.push({ fixed: join(l1, withDigit), change: "digit", from: l2[f.check], to: String(checkDigit(data)) })
    issues.push({ kind: "check", field: f.field, found: l2[f.check], expected: String(checkDigit(data)), fixes: fixes.slice(0, 2) })
  }
  checks.composite = compositeOk(l2) ? (touched(0, 9) || touched(13, 19) || touched(21, 43) ? "pending" : "ok") : "fail"
  if (!issues.some((i) => i.kind === "check") && !compositeOk(l2)) {
    const expected = String(checkDigit(compositeOf(l2)))
    issues.push({ kind: "check", field: "composite", found: l2[43], expected, fixes: [{ fixed: join(l1, put(l2, 43, expected)), change: "digit", from: l2[43], to: expected }] })
  }

  const names = l1.slice(5).replace(/<+$/, "")
  const [surname, ...given] = names.split("<<")
  const fields: MrzFields = {
    documentCode: l1.slice(0, 2),
    issuingState: l1.slice(2, 5).replace(/</g, ""),
    surname: surname.replace(/</g, " ").trim(),
    givenNames: given.join(" ").replace(/</g, " ").replace(/\s+/g, " ").trim(),
    number: l2.slice(0, 9).replace(/<+$/, ""),
    nationality: l2.slice(10, 13).replace(/</g, ""),
    birthDate: date(l2.slice(13, 19), "birth", now),
    sex: (["M", "F", "X"].includes(l2[20]) ? l2[20] : "<") as MrzFields["sex"],
    expiryDate: date(l2.slice(21, 27), "expiry", now),
    personalNumber: l2.slice(28, 42).replace(/<+$/, "").replace(/</g, " "),
  }
  const dob = l2.slice(13, 19)
  if (!fields.birthDate && /^[\d<]{6}$/.test(dob) && dob.includes("<") && /^(\d\d|<<)(\d\d|<<)(\d\d|<<)$/.test(dob)) {
    const yy = /^\d\d/.test(dob) ? +dob.slice(0, 2) : null
    issues.push({ kind: "unknownBirthDate", year: yy === null ? null : 2000 + yy > now.getUTCFullYear() ? 1900 + yy : 2000 + yy })
  } else if (!fields.birthDate) issues.push({ kind: "badDate", field: "birthDate", value: dob })
  if (!fields.expiryDate) issues.push({ kind: "badDate", field: "expiryDate", value: l2.slice(21, 27) })
  // 9303-3 §4.6: a name that fills the last position may have been cut short.
  if (l1[43] !== "<") issues.push({ kind: "truncated" })
  if (fields.expiryDate) {
    const days = Math.round((Date.parse(fields.expiryDate) - Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())) / 86_400_000)
    if (days < 0) issues.push({ kind: "expired", date: fields.expiryDate, days: -days })
    else if (days <= 182) issues.push({ kind: "expiresSoon", date: fields.expiryDate, days })
  }
  const blocking = issues.some((i) => !["truncated", "expiresSoon", "expired", "unknownBirthDate"].includes(i.kind))
  return { lines: [l1, l2], fields, issues, valid: !blocking, checks }
}
